-- QuestLocalization_Lv1_10.lua
_G.QuestLocalization_Lv1_10 = {
    [66] = {
        nameES = "Un Frontero de gran mérito",
        objectivesES = {
            "'He oído hablar de todas las buenas acciones que has realizado, ${PLAYER}. ¡Realmente eres uno de los mejores Fronteros y mereces el agradecimiento de todos los habitantes de la Comarca!\n\n'No somos muy aficionados a los uniformes, pero debo decir que te has ganado otra pluma para tu gorra. Acéptala con mi agradecimiento.'",
            "'Has hecho grandes cosas por muchos habitantes de la Comarca, ${PLAYERNAME:Frontero[m]|Frontera[f]} . Ve a contar tus hazañas al Oficial adjunto Bodo Bonce, cerca del Agujero Municipal de Cavada Grande.'",
            "'¿Qué noticias hay de los límites, ${PLAYERNAME:amigo[m]|amiga[f]} ?'",
            "'¡Has demostrado ser todo ${PLAYERNAME:un Frontero[m]|una Frontera[f]} !'",
            "'Ve a ver al Oficial adjunto Bodo Bonce, cerca del Agujero Municipal de Cavada Grande. ¡Estará muy contento de escuchar todas tus hazañas!'",
            "'¡Hola, ${PLAYERNAME:Frontero[m]|Frontera[f]} !'",
            "Has demostrado ser ${PLAYERNAME:un Frontero[m]|una Frontera[f]} de gran mérito.",
            "'Te doy las gracias por todo lo que has hecho, ${PLAYERNAME:Frontero[m]|Frontera[f]} .'",
            "El Oficial adjunto Bodo Bonce se encuentra cerca del Agujero Municipal de Cavada Grande.\n\nSe te ha aconsejado que vayas a contarle tus muchas hazañas en beneficio de los habitantes de la Comarca.",
            "Un Frontero de gran mérito",
        }
    },
    [67] = {
        nameES = "Un Frontero de gran mérito",
        objectivesES = {
            "'He oído hablar de todas las buenas acciones que has realizado, ${PLAYER}. ¡Realmente eres uno de los mejores Fronteros y mereces el agradecimiento de todos los habitantes de la Comarca!\n\n'No somos muy aficionados a los uniformes, pero debo decir que te has ganado otra pluma para tu gorra. Acéptala con mi agradecimiento.'",
            "'¿Qué noticias hay de los límites, ${PLAYERNAME:amigo[m]|amiga[f]} ?'",
            "'Has hecho grandes cosas por muchos habitantes de la Comarca, ${PLAYERNAME:Frontero[m]|Frontera[f]} . Ve a contar tus hazañas al Oficial adjunto Bodo Bonce, cerca del Agujero Municipal de Cavada Grande!'",
            "'¡Has demostrado ser todo ${PLAYERNAME:un Frontero[m]|una Frontera[f]} !'",
            "'Ve a ver al Oficial adjunto Bodo Bonce, cerca del Agujero Municipal de Cavada Grande. ¡Estará muy contento de escuchar todas tus hazañas!'",
            "'¡Hola, ${PLAYERNAME:Frontero[m]|Frontera[f]} !'",
            "Has demostrado ser ${PLAYERNAME:un Frontero[m]|una Frontera[f]} de gran mérito.",
            "'Te doy las gracias por todo lo que has hecho, ${PLAYERNAME:Frontero[m]|Frontera[f]} .'",
            "El Oficial adjunto Bodo Bonce se encuentra cerca del Agujero Municipal de Cavada Grande.\n\nSe te ha aconsejado que vayas a contarle tus muchas hazañas en beneficio de los habitantes de la Comarca.",
            "Un Frontero de gran mérito",
        }
    },
    [74] = {
        nameES = "Un Breve Respiro",
        objectivesES = {
            "Eluna te pidió que ayudaras a la gente de Lhan Garan.\n\nAyuda a la gente de Lhan Garan.",
            "Habla con Eluna",
            "Eluna quiere que ayudes a la gente de Lhan Garan.",
            "Ayuda a Madog y Teilo Gwyniad",
            "'Aún estoy intentando entender por qué los Draig-lûth están aquí. Cuando nos marchamos para establecer Lhan Garan, sin duda fue una fuente de tensión, pero Talfryn aseguró la promesa de que nos dejarían en paz. Deja que investigue esto. No te preocupes, prometo mantenerme a salvo.\n\n'Hasta que tenga noticias, ¿podrías ayudar a algunas personas del pueblo?'",
            "Ayuda a Marget",
            "'Tienes una habilidad inquietante para aparecer en el momento justo, amigo. Tengo noticias.'",
            "Ayuda a Culhuc",
            "Has ayudado a varias personas en el pueblo.\n\nEs hora de regresar con Eluna en Lhan Garan.",
            "Un Breve Respiro",
        }
    },
    [85] = {
        nameES = "A Brutal Reversal",
        objectivesES = {
            "Defeat the siege-leader and his forces on the captured wall",
            "Defeat the forces of Mordor that have overtaken part of the wall of Minas Tirith before they can use Gondor's own siege equipment against it.",
            "Forces of Mordor have overtaken part of the outer wall of Minas Tirith and intend to use Gondor's own siege weaponry against the inhabitants of the city.\n\nThis quest starts with <rgb=#FFFF00>empty</rgb> Merit Rating.\n\n<rgb=#00FF00>Merit Gain:</rgb>\n* Defeat the siege-leader atop his tower\n* Defeat the Orkish forces on the wall\n* Prevent the Orcs from destroying siege equipment\n* Destroy enemy barricades",
            "A Brutal Reversal",
        }
    },
    [86] = {
        nameES = "A Brutal Reversal",
        objectivesES = {
            "Defeat the siege-leader and his forces on the captured wall",
            "Defeat the forces of Mordor that have overtaken part of the wall of Minas Tirith before they can use Gondor's own siege equipment against it.",
            "Forces of Mordor have overtaken part of the outer wall of Minas Tirith and intend to use Gondor's own siege weaponry against the inhabitants of the city.\n\nThis quest starts with <rgb=#FFFF00>empty</rgb> Merit Rating.\n\n<rgb=#00FF00>Merit Gain:</rgb>\n* Defeat the siege-leader atop his tower\n* Defeat the Orkish forces on the wall\n* Prevent the Orcs from destroying siege equipment\n* Destroy enemy barricades",
            "A Brutal Reversal",
        }
    },
    [99] = {
        nameES = "Llamado a la Cena",
        objectivesES = {
            "Rosentyl Flutch te ha pedido que avises a sus hijos que ya es hora de comer.\n\nLos hijos de Rosentyl pueden encontrarse por Clegur.",
            "Rosentyl está en Clegur.\n\nDeberías decirle a Rosentyl que ya avisaste a todos sus hijos para que vengan a disfrutar la comida que preparó",
            "Niños avisados para que vengan a comer (${CURRENT}/${MAX})",
            "Dile a los niños que vengan a comer (${CURRENT}/${MAX})",
            "Una madre agotada tiene las manos llenas preparando una comida para sus cinco hijos.",
            "'¿Hora de comer? Oh, supongo que no debería haberme comido todas esas bayas..... ¡eh! Siempre hay lugar para más.'",
            "'¡Por fin! ¡Han pasado horas desde la última vez que comí!'",
            "'Oh, hola. Sí, supongo que puedo volver a casa a cenar.'",
            "'¿Quién eres tú? ¿Qué? ¿Comida ya? ¡Espléndido!'",
            "'Si vienes buscando comida, no tengo nada para ti. No pretendo ofender, pero con cinco niños hambrientos no queda ni un bocado para nadie más. Pero dime, podría ofrecerte unas monedas si pudieras ayudarme.\n\n'Los niños están afuera jugando y recolectando o lo que sea que hacen para volver cubiertos de barro, cardos y oliendo a un estercolero. ¿Podrías avisarles que ya es hora de comer?'",
            "'¿La comida está lista? ¡De acuerdo! ¡Vuelvo enseguida!'",
            "Llamado a la Cena",
            "Regresa con Rosentyl",
            "'¿Los niños ya vienen todos? ¡Encantador! ¡Hiciste un trabajo estupendo! Supongo que no dejarías tus aventuras para dedicarte a ser niñera, ¿eh? Ja, ja\n\n'Bueno, tienes mi agradecimiento'",
        }
    },
    [110] = {
        nameES = "Una Causa de Preocupación",
        objectivesES = {
            "'Durglup es una criatura terriblemente cruel, dispuesta a arremeter incluso contra sus propios hermanos. Es un servidor poderoso y debe ser destruido.'",
            "'Es bueno saber que la amenaza que representaba esta criatura ha desaparecido. Te agradezco tus esfuerzos allí.\n\n'Siempre recordaré tus hazañas de este día, ${PLAYER}.'",
            "Dol Ringwest se encuentra al oeste de Duillond.\n\nCalengil desea expulsar el mal de las ruinas de Dol Ringwest. Te ha pedido que te dirijas a las ruinas y busques al líder de los trasgos, Durglup.",
            "Una Causa de Preocupación",
            "Calengil se encuentra en Duillond, al este de Dol Ringwest.\n\nDurglup resultó ser un desafío para el que estabas bien preparado. Ya no contamina las ruinas de Dol Ringwest. Debes regresar ante Calengil de inmediato.",
            "Derrotaste a Durglup",
            "'Mi deber con esta tierra no estará cumplido hasta que el terror que trajo la ruina aquí sea expulsado. Tus esfuerzos hasta ahora han sido sinceros y han demostrado que tú también deseas ver estas tierras restauradas y purificadas del mal que las ha afligido.\n\n'Mientras estés en las ruinas, te pido que busques al líder de los trasgos allí, Durglup. Es un trasgo particularmente perverso y no debe ser subestimado.\n\n'Encontrarás a esta criatura en los confines de Dol Ringwest, al oeste de Duillond. Regresa ante mí cuando la bestia haya sido abatida.'",
            "Derrota a Durglup",
            "Calengil quiere que destruyas al trasgo Durglup en Dol Ringwest. Cree que este trasgo es el líder de las fuerzas allí y, por tanto, responsable de la profanación de las ruinas.",
            "Habla con Calengil en Duillond",
        }
    },
    [134] = {
        nameES = "Un fuego purificador",
        objectivesES = {
            "Prende fuego a las madrigueras cubiertas de telarañas en Jâr Obadal (${NUMBER}/${TOTAL})",
            "Encuentra y derrota a Jûkhtar la Voraz en Jâr Obadal.",
            "Encuentra y derrota a Jûkhtar la Voraz en Jâr Obadal",
            "'Estas arañas, incluso muertas, me ponen los pelos de punta. Me alegra que hayas podido reducir su número. ¡Vamos a volver con Zajâna para contarle las buenas noticias!'",
            "¡Jûkhtar grita de rabia y hambre al verte!",
            "Derrota a las arañas en Jâr Obadal (${NUMBER}/${TOTAL})",
            "Derrota a las arañas dentro de Jâr Obadal y prende fuego a su red de telarañas.",
            "Jûkhtar se derrumba, muriendo, en una masa de extremidades temblorosas",
            "Un fuego purificador",
            "Las arañas salvajes dentro de las cuevas de Jâr Obadal han acosado durante mucho tiempo a viajeros y mercaderes a lo largo del Gran Camino. Prende fuego a sus telarañas y acaba con su amenaza de una vez por todas.",
        }
    },
    [173] = {
        nameES = "Un corte por encima",
        objectivesES = {
            "Derrota a los vigías corsarios (${NUMBER}/${TOTAL})",
            "Lleva la lucha a Ghasaphâr y sus corsarios. Oblígalos a abandonar su asentamiento en Kan Skûrja en el Cabo de Umbar.",
            "Derrota a los marineros corsarios (${NUMBER}/${TOTAL})",
            "'¡Ja! ¡Les has dado una buena lección a esos corsarios! Volvamos a Umbar para que puedas compartir las buenas noticias.'",
            "Derrotaste a los brutos corsarios (${NUMBER}/${TOTAL})",
            "Capitán Corsario Ghasaphâr derrotado",
            "Derrota a los brutos corsarios (${NUMBER}/${TOTAL})",
            "Un corte por encima",
            "¡Ghasaphâr aparece para luchar!",
            "Un grupo de Corsarios establecidos en el Cabo de Umbar ha estado atacando en la Bahía de Belfalas, hostigando barcos mercantes. ¡Llévalos a la lucha!",
            "Derrotaste a los vigías corsarios (${NUMBER}/${TOTAL})",
            "Derrota al Capitán Corsario Ghasaphâr.",
            "Derrota al Capitán Corsario Ghasaphâr",
            "Marineros corsarios derrotados (${NUMBER}/${TOTAL})",
        }
    },
    [192] = {
        nameES = "Un oscuro tesoro",
        objectivesES = {
            "¡Los corsarios han llegado antes que tú al tesoro! Derrota a los corsarios y reclama la cache de tesoro para los pueblos libres de Umbar.",
            "Corsarios derrotados (${NUMBER}/${TOTAL})",
            "Se han reportado grandes tesoros enterrados en una isla poco transitada. Se te ha encomendado la tarea de recuperar el tesoro para ayudar a la restauración de Umbar.",
            "Encuentra y derrota a la capitana Shêndi Ojo Gris",
            "Un oscuro tesoro",
            "Encuentra y recoge el tesoro",
            "Derrota a los corsarios (${NUMBER}/${TOTAL})",
            "Has derrotado a la capitana Shêndi Ojo Gris",
            "'¡Lo encontraste! ¡Tanto oro! Estoy seguro de que, eh, la cantidad adecuada llegará a los cofres de Umbar. ¡Vamos a llevarte de regreso a Umbar Baharbêl!'",
            "¡La capitana Shêndi Ojo Gris ha llegado para reclamar la cache de tesoro como suya!",
            "¡Al tocar la moneda, espíritus malditos saltan del cofre!",
            "Derrota a la capitana Shêndi Ojogris",
        }
    },
    [198] = {
        nameES = "Una Flor Mortal",
        objectivesES = {
            "'Gracias, amable ${RACE}. Si logramos evitar que las plantas se propaguen, quizá mueran por sí solas. Las criaturas de la Puerta de Thorin están más seguras gracias a ti.'",
            "Has destruido plantas de la Flor de Skorgrím (${NUMBER}/${TOTAL})",
            "Destruye plantas de la Flor de Skorgrím (${NUMBER}/${TOTAL})",
            "'Has hecho bien en detener la propagación de la \\qFlor de Skorgrím\\q. Tienes mi agradecimiento.'",
            "Erynwen se encuentra en el centro del Patio de Frerin.\n\nHas destruido algunas plantas de la Flor de Skorgrím, como pidió Erynwen.",
            "Una Flor Mortal",
            "Una planta venenosa llamada \\qFlor de Skorgrím\\q amenaza la vida silvestre de Ered Luin. Sin alguien que detenga su propagación, la vida de muchas criaturas podría estar en riesgo.",
            "'Una planta venenosa llamada Flor de Skorgrím florece a lo largo del sendero que conduce a los Túneles de Piedramusgo, justo al noroeste de aquí. Detén la propagación de la planta destruyendo cualquier flor que encuentres.'",
            "La Flor de Skorgrím florece a lo largo del sendero que conduce a los Túneles de Piedramusgo, al noroeste del Patio de Frerin.\n\nDestruye las flores venenosas, para que no se propaguen por la ladera de la montaña.",
            "'Hay una planta peligrosa que se extiende desde la cueva de trasgos al noroeste de aquí. Los enanos la llaman \\qFlor de Skorgrím\\q, en honor a aquel vil enano muerto hace muchos años cuando cayó Edhelion.\n\n'Esta mala hierba es ajena a Ered Luin y su propagación debe ser contenida. La planta es muy mortal, y temo que muchas criaturas desprevenidas serán envenenadas si pastan sobre ella.\n\n'No podemos erradicarla de un solo golpe, pero podemos detener su propagación. Las plantas florecen a lo largo del sendero que conduce a los Túneles de Piedramusgo, al noroeste de aquí. Arranca algunas de estas plantas y tendrás tu recompensa.'",
        }
    },
    [260] = {
        nameES = "Una Molestia Emplumada",
        objectivesES = {
            "Hendrevail derrotados en el Valle de Thráin (${NUMBER}/${TOTAL})",
            "'¡Los caminos deberían estar seguros, al menos por un tiempo, gracias a ti, ${PLAYER}!'",
            "Habla con Ketill en Noglond",
            "'Aún hay hendrevail infestando los caminos. Continúa tu caza de las aves y regresa conmigo cuando hayas reducido sus números.'",
            "Derrota hendrevail en el Valle de Thráin (${NUMBER}/${TOTAL})",
            "'Nadie había hecho un esfuerzo por mantener los caminos despejados desde hace mucho. ¡Bueno, eso va a cambiar!'",
            "Feroces hendrevail plagan la Valle de Thráin, haciendo que viajar por la Valle sea peligroso.",
            "'Los hendrevail han crecido a números alarmantes durante el último año y ahora los caminos desde la Mansión de Thorin hasta Gondamon son inseguros.\n\n'${PLAYER}, si pudieras prestar tu ayuda una vez mas, patrulla los caminos al norte y al sur de Noglond y caza cualquier hendrevail que encuentres.\n\n'Viajeros recientes que pasaron por nuestro puesto dijeron haber visto grandes cantidades de hendrevail al otro lado del río, hacia el sur. Si buscas el origen de sus números, ese lugar es tan probable como cualquier otro.'",
            "Una Molestia Emplumada",
            "'Gracias por ayudar a mantener los caminos despejados. ¡Si no es mucha molestia, por favor no le digas a nadie que necesité ayuda!'",
            "El camino corre hacia el norte desde Noglond a través del Valle de Thráin hasta la Mansión de Thorin.\n\nKetill te ha pedido patrullar a lo largo del camino por el Valle de Thráin y reducir la cantidad de hendrevail. También mencionó que pueden encontrarse grandes números de hendrevail al sur del río, al sur de Noglond.",
            "Ketill está en Noglond, al sur de la Mansión de Thorin.\n\nDebes regresar con Ketill e informarle los resultados de tu patrulla.",
        }
    },
    [276] = {
        nameES = "Faltan algunas páginas",
        objectivesES = {
            "El diario que llevaste de regreso a Wilimar Bolger tenía muchas hojas faltantes, gracias a que fue sacudido y desgarrado por algunas bestias salvajes.",
            "Hojas de diario recogidas (${NUMBER}/${TOTAL})",
            "Se pueden encontrar lobos al este de Bolgovado.\n\nSin las hojas faltantes, será imposible determinar quién disparó la flecha en la puerta de Wilimar Bolger, ni por qué. Wilimar sospecha que los lobos destrozaron el diario y te ha pedido que intentes recuperar las hojas de ellos.",
            "'¡Maravilloso, las has encontrado todas! ¡Gracias! Ahora a ver qué significa esto...\n\n'Por Eru, esto es interesante... ¡y preocupante! Necesitaré un momento más para leerlo, pero parece que el autor de este diario era un hombre llamado \\qCallum\\q. ¡Y la historia que cuenta es asombrosa!\n\n'Por difícil que sea de creer, parece que un antepasado lejano mío mató a uno de los suyos en una gran batalla. Y, oh cielos... él quiere vengarse de mí...'",
            "'¿Has encontrado todas las hojas perdidas del diario? Parece que los lobos destrozaron el diario, así que mata a las bestias que encuentres cerca de Bolgovado y mira si llevan alguna de las hojas del diario.\n\n'Parece que faltan unas tres hojas, y necesitaré las tres si quiero saber quién está detrás de la flecha en mi puerta y si me quiere hacer daño!'",
            "'Oh, cielos, esto no es bueno, nada bueno. Faltan muchas hojas del diario, como si hubiera sido sacudido y desgarrado por una bestia. Mira aquí, ¿ves las marcas de dientes?\n\n'¡Por el amor de Eru, esas marcas de dientes podrían ser de un lobo! Me pregunto si alguna de las bestias tomó las páginas, tal vez para forrar sus guaridas. Sí, sí, sé que suena extraño, pero he escuchado uno o dos relatos de que hacen tales cosas.\n\n'Si puedes, mata algunos lobos al este de aquí y mira si tienen alguna de las hojas del diario. Me faltan unas tres hojas en total. ¡Cuando tenga todas las páginas, debería poder ver qué tramaba el autor del diario!'",
            "Faltan algunas páginas",
            "Recoge hojas de diario (${NUMBER}/${TOTAL})",
            "Lleva las hojas del diario a Wilimar Bolger",
        }
    },
    [287] = {
        nameES = "A Flanking Foe",
        objectivesES = {
            "Aid Gimli and his allies in completing their patrol (${VALUE}/4)",
            "Aid Gimli in removing enemy threats that have managed to flank the defenders on the wall, while others work to rescue supplies from besieged structures within the deep.",
            "A labourer has been defeated (${NUMBER}/${TOTAL})",
            "Gimli has rallied a group of inexperienced soldiers to help in defeating the Orcs who have crept through the culvert in an attempt to flank the wall's defenders. As Gimli advances to secure the Deep, the enemy catapults are causing destruction to the fortifications and stores beyond the wall. Brave labourers have attempted to salvage any supplies within the structures before they are lost in the ongoing siege.\n\nMerit Rating\n\nThis quest starts with <rgb=#FFFF00>Partial</rgb> Merit Rating.\n\n<rgb=#00FF00>Moderate Merit Gain</rgb>\n* Labourer recovers supplies from store-house\n\n<rgb=#FF0000>Moderate Merit Loss</rgb>\n* Rohirrim Labourer becomes defeated\n* Rohirrim Cadet becomes defeated",
            "Do not allow labourers to be defeated (${NUMBER}/${TOTAL})",
            "A Flanking Foe",
        }
    },
    [342] = {
        nameES = "Un Regalo para Amdir",
        objectivesES = {
            "Un Regalo para Amdir",
            "Celandine preparó un té medicinal de arándanos para Amdir, con la esperanza de que lo fortaleciera y animara contra la sombra que ha caído sobre él.",
            "'¿Ese... té huele a arándanos? Eso fue muy... dulce por parte de Celandine, y muy bueno de tu parte traerle los ingredientes. Lamento decirlo, pero no puedo beberlo ahora. No... no me siento lo bastante bien en este momento.\n\n'Fingiré beberlo. Debes decirle a Celandine que disfruté su té. Por favor... ¡no le digas que su amabilidad fue desperdiciada en mí!'",
            "Amdir solo finge beber el té; se ve aún más pálido que antes...",
            "Asegúrate de que Amdir beba el té de arándanos",
            "Regresa con Celandine y miente por el bien de Amdir",
            "'...'\n\nLos ojos de Amdir están ahora cerrados, y ya no hace esfuerzo por hablar en este momento. Su rostro está tan pálido como el hielo.",
            "'¿Ese té lo animó? ¡Sabía que lo haría! El té de arándanos siempre me levanta el ánimo, y sé que sería especialmente dulce si viniera de parte de los dos, ${PLAYER}.\n\n'Sé que Amdir estará de pie pronto — ¡es tan valiente!'",
            "'¡Rápido ahora! No debes dejar que el té se enfríe. ¡Espero que haga que Amdir se sienta mejor!'",
            "Esta misión no puede completarse fuera de la introducción.",
            "Celandine está al otro lado del camino de Amdir, en el centro de Archet.\n\nDebes regresar con Celandine y mentir en nombre de Amdir. Él no bebió su té, pero no quiere que ella se desilusione...",
            "'¿No huele delicioso este té de arándanos? Aún me recuerda a mi Abuela, que me hacía esto cuando estaba indispuesta, aunque hace mucho que mi Abuela ya no está.\n\n'Fuiste tan amable al recoger esas bayas silvestres para mí, ¡así que no me quedaré con todo el crédito! ¿Por qué no llevas esta buena infusión a Amdir para que pueda agradecerte él mismo?\n\n'¡Asegúrate de que se lo beba todo!'",
            "Amdir está sentado al otro lado del camino de Celandine, en el centro de Archet.\n\nDebes llevar a Amdir el té restaurador de arándanos de Celandine para ayudarlo a recuperar su fuerza y su claridad.",
        }
    },
    [346] = {
        nameES = "Un regalo para el norte",
        objectivesES = {
            "Un regalo para el norte",
            "'¿Estás ${PLAYERNAME:listo[m]|lista[f]} para partir?\n\nAsegúrate de que tu grupo también esté preparado, porque sin duda necesitaremos su ayuda para matar a ese troll de piedra.'",
            "'¡Esos Duramano son unos ladrones y traicioneros, pero me cuesta creer que incluso ellos dejarían vivir a un troll!'",
            "Habla con Ulfar",
            "'Bien hecho. Sin duda mereces esta recompensa.'",
            "'¿Quién hubiera pensado que el robo de una vaca destaparía un complot como este? ¡Debemos frustrar los planes de Olwir y, si ha capturado un troll, debemos matarlo!\n\nPor suerte, he averiguado dónde acampan Olwir y sus enanos. Se encuentran al norte del Pantano de los Juncos. Sin embargo, entrar en el campamento y matar a ese troll de piedra, si es que tienen uno, no será fácil. Necesitaremos ayuda.\n\nReúne un grupo de guerreros —si es que puedes encontrar alguno en estas tierras— y vuelve aquí. Asegúrate de reunir guerreros robustos, porque la batalla que nos espera no será fácil.'",
            "Ulfar ha regresado a Ojo de Aguja.\n\nComo has tenido éxito en tu misión, deberías volver con Ulfar para contarle lo sucedido.",
            "Por las órdenes que encontraste, Ulfar ha sabido que Olwir planea capturar un troll de piedra que merodea por el Pantano de los Juncos y entregarlo como regalo a los Duramano del norte. La vaca que robó a Filibert era el cebo para atrapar a la criatura.",
            "El campamento de Olwir está en las zonas norte del Pantano de los Juncos.\n\nUlfar ha decidido que el plan de Olwir debe ser detenido y te ha pedido que reúnas un grupo de guerreros para acompañarlo al campamento. Una vez allí, planea infiltrarse y matar a cualquier troll de piedra que los enanos de Olwir hayan capturado.",
            "'Gracias por tu ayuda, ${RACE}. No sé qué travesura tramaban los Duramano, pero seguro que no era nada bueno!'",
            "'¡Que un enano pudiera soportar la presencia de un troll es impensable! No importa... ahora está muerto, y Olwir también.'",
        }
    },
    [347] = {
        nameES = "Un regalo para el norte",
        objectivesES = {
            "'¡Bien hecho! Me impacienté esperando y vine a ver cómo te estaba yendo, pero parece que lo hiciste bien sin mí. Ese troll de piedra está muerto, y parece que Olwir también. Pagó un alto precio por su crimen, robar una vaca a Filibert. Con él fuera del camino, estos enanos no deberían molestar mucho más al Pantano de los Juncos.\n\n'Has hecho un buen trabajo hoy, ${PLAYERNAME:amigo mío[m]|amiga mía[f]}. Tienes mi agradecimiento. ¿Estás ${PLAYERNAME:listo[m]|lista[f]} para partir?'",
            "Has derrotado a los enanos que custodiaban la puerta. Deberías avanzar hacia el campamento en busca de Olwir o de un troll de piedra.",
            "Enfrenta a Olwir",
            "Has encontrado a Olwir y derrotado a los guardias que lo protegían. ¡Tiene un troll de piedra enjaulado! Deberías enfrentarte a Olwir.",
            "Un regalo para el norte",
            "Desafía a los Duramano frente a la puerta",
            "Has viajado a las afueras del campamento enano en el Pantano de los Juncos. Allí esperas poner fin al plan del enano Olwir de capturar un troll de piedra y dárselo como regalo al enano Skorgrím en el norte.",
            "Acércate a la puerta",
            "Debes encontrar una manera de entrar en el campamento enano. Tal vez desafiar a los enanos a un combate los haga abrir la puerta.",
            "Busca en el campamento a Olwir",
            "<rgb=#FF0000>Abofetear</rgb> al rastreador Duramano",
            "Derrota al troll de piedra",
            "Los Duramano han abierto la puerta para responder a tu desafío.",
            "Parece que Olwir ya no es un problema, pero ahora tienes uno más grande: un troll de piedra que debe ser derrotado.",
            "Eh... está bien, ¡derrota al troll de piedra!",
            "Los Duramano han abierto la puerta para responder a tu desafío. Deberías hacer algo que inicie el combate.",
            "Debes encontrar una manera de entrar en el campamento enano.",
            "<rgb=#FF0000>Desafía</rgb> a los Duramano frente a la puerta",
            "Espera a los Duramano",
            "Has encontrado a Olwir, junto con un troll enjaulado.",
            "Has encontrado a Olwir, y tiene un troll de piedra enjaulado. Deberías derrotar a los Duramano que lo protegen.",
            "Derrota a los guardias de Olwir",
        }
    },
    [392] = {
        nameES = "La alegría vuelve a Hobbiton",
        objectivesES = {
            "La alegría vuelve a Hobbiton",
            "El Tío Gamyi se encuentra delante de su agujero en Bolsón de Tirada.\n\nDeberías ir a decirle que has frustrado los planes de Lobelia",
            "'¿Así que Lobelia pensaba guardarse toda la mejor comida para ella y los suyos? Me alegra que hayas podido poner las cosas en su sitio; y el resto de la gente aquí en Hobbiton piensa lo mismo.\n\n'Simplemente nos pareció correcto traerte algo. Lobelia tenía razón, en cierto modo: no tenemos mucho que ofrecer, ¡pero compartimos lo que podemos, especialmente con aquellos que nos han dado tanto como tú!\n\n'Nos gustaría que te quedaras con este árbol de Yule. Es un trasplante; mi sobrino Halfast lo trajo de la Cuaderna del Norte. Íbamos a plantarlo en el patio, pero viendo cómo nos has ayudado... bueno, Caléndula pensó que lo mejor sería que te lo quedaras para tu casa.'",
            "Habéis desbaratado el plan de Lobelia, quería quedarse para ella los mejores alimentos del banquete de Yule.\n\n<rgb=#FF0000>NOTA: Esta misión se eliminará de tu diario de misiones cuando el festival actual haya finalizado.</rgb>",
            "'¡Bueno, parece que vuestro jueguecito funcionó! ¡Pamplinas!   \n\n'Otra fiesta arruinada, y no precisamente gracias a ti. ¿Por qué no vas a contarle a tu buen amigo Hamfast lo que has hecho aquí? No me cabe duda de que él te incitó a todo esto, con su querida Caléndula enviada aquí solo para avergonzarme de esa manera.'",
        }
    },
    [399] = {
        nameES = "Una comida abundante",
        objectivesES = {
            "Jabalíes de Khudi derrotados (${NUMBER}/${TOTAL})",
            "Recoger huevos (${NUMBER}/${TOTAL})",
            "Una comida abundante",
            "Con un fuerte cacareo, un pollo particularmente agresivo ha aparecido para defender el rebaño.",
            "Derrota al pollo particularmente agresivo en la cima de la colina",
            "Huevos recolectados (${NUMBER}/${TOTAL})",
            "Pollos de Khudi derrotados (${NUMBER}/${TOTAL})",
            "'Hola. ¡Estos huevos son exactamente lo que necesitábamos! Regresemos a Iridír juntos.'",
            "Derrota a los jabalíes de Khudi (${NUMBER}/${TOTAL})",
            "Encuentra y derrota al pollo particularmente agresivo en Shegdush, en la cima de la colina.",
            "Derrota a los pollos de Khudi (${NUMBER}/${TOTAL})",
            "Tu misión es viajar a Shegdush y recolectar huevos y reducir el número de pollos y jabalíes en la zona.",
        }
    },
    [403] = {
        nameES = "El botín escondido",
        objectivesES = {
            "'Está bien, has encontrado las hojas. Dámelas. Ahora cumpliré mi parte del trato. Ese Tuk que buscas... Gerebert era su nombre, ¿no? ¿Y se escondió en uno de mis carros de hojas?\n\n'Bueno, yo no lo he visto. ¿Eh? No dije que hubiera visto a ese Tuk tuyo. Solo dije que te diría lo que sabía. ¡Y eso es todo lo que sé! ¡Ahora vete!'",
            "El botín escondido",
            "Esilia Tuk se encuentra en el centro de Alforzaburgo.\n\nLongo Madriguera aceptó decirte lo que sabía sobre Gerebert a cambio de un barril de hojas que había escondido en una guarida de osos. Sin embargo, cuando se lo llevaste, Longo te reveló que no sabía nada sobre Gerebert. Deberías volver con Esilia Tuk y contarle lo que ha pasado.",
            "'Antes de decirle dónde está ese tonto de Tuk que busca, necesito que me haga un pequeño favor. Verá, mi hierba para pipa es conocida en toda la Comarca, y un poco más allá, y eso significa que mucha gente viene a pedirme hojas.\n\n'Bueno, mi cosecha actual aún no está lista para la recolección, pero soy un hobbit listo, ¿sabe? Cuando los osos dormían en invierno, escondí un barril de hojas en una de sus guaridas, para días lluviosos como hoy.\n\n'Vaya a las guaridas de osos al sur de aquí y encuentre ese barril de hojas. Cuando me lo traiga, le diré lo que sé sobre ese Tuk.'",
            "'¡Oh, qué terrible! Ese Longo es un tipo grosero. Siento mucho que le haya jugado esa mala pasada. La próxima vez que lo vea, tendré unas palabras con él.\n\n'Ahora, volviendo al asunto de Gerebert. Creo que acabo de tener una idea sobre a quién más podríamos preguntar, si todavía estás ${PLAYERNAME:dispuesto[m]|dispuesta[f]} a salir a buscarlo.'",
            "Lleva un barril de hierba para pipa a Longo Madriguera",
            "El diario de Gerebert Tuk reveló que había aceptado un desafío para esconderse en uno de los carros de hojas de Longo Madriguera. Esilia Tuk te ha pedido que le ayudes a buscar a su primo.",
            "Las guaridas de osos se encuentran al sur de la granja de Longo Madriguera.\n\nEsilia Tuk te ha pedido que hables con Longo Madriguera sobre su primo Gerebert. Longo ha exigido que le hagas un favor antes de hablar. Te ha dicho que su hierba para pipa tiene mucha demanda, pero que su cosecha actual aún no está lista para la recolección. Te ha encargado que recuperes un barril de hierba para pipa que escondió en una guarida de osos durante el invierno.",
            "'¿Dónde está ese barril de hojas? Si quieres saber lo que sé sobre tu amigo Tuk, me traerás ese barril.\n\n'Escondí las hojas en una de las guaridas de osos al sur de aquí. No debería ser muy difícil de encontrar.'",
            "'¿Por qué sigues ahí ${PLAYERNAME:parado[m]|parada[f]}? Te dije todo lo que sabía sobre ese Tuk que buscabas... ¡Y resulta que no sabía nada!\n\n'¡Ahora vete!'",
        }
    },
    [408] = {
        nameES = "Un Hogar Hobbit Lejos del Hogar",
        objectivesES = {
            "Tras un largo viaje desde las tierras del Valle de la Niebla que te condujo hasta la aldea fronteriza de Musgovilla, en la Ciénaga de los Cisnes, te has topado con un hobbit de lo más curioso. No es un hobbit ribereño de Lyndelby, ni uno de los Fuertes de la Ciénaga de los Cisnes, ni tampoco uno de sus escurridizos primos de los que se rumorea que habitan en Enedwaith: es un hobbit de una tierra llamada la Comarca.",
            "'¡Vaya, vaya! Creo que ya hemos tenido más que suficiente emoción por hoy. No recuerdo haberte visto por Musgovilla, ${PLAYERNAME:viajero[m]|viajera[f]}. Aunque imagino que me habría sido difícil ver cualquier cosa mientras me escondía en el armario de alguno de estos buenos vecinos durante aquella incursión. He oído que ayudaste a poner fin a esos trasgos descomunales, y debo agradecértelo. ¿Cómo te llamas?'\n\nTe presentas, y Fridolin Tuk se presenta a su vez.\n\n'....... un nombre curioso para un hobbit de lo más curioso. Caramba, tienes un parecido notable con el viejo Bandobras Tuk —el Toro Bramador, como lo llamamos los Tuk— sí, un gran parecido en efecto, al menos en lo que a la altura se refiere. ¿Podrías ser ${PLAYERNAME:uno de mis primos perdidos[m]|una de mis primas perdidas[f]} hace mucho tiempo? ¿No? ¿Quizá seas de los Nortuk, entonces?'\n\nLe dices a Fridolin que no eres uno de los Tuk, ni un Nortuk, ni un Toro Bramador —sea lo que sea eso— ni nada por el estilo. Dices que procedes de un lugar más allá de las Montañas Nubladas, y que has viajado a Musgovilla como solo uno de los muchos destinos de un largo periplo desde tu tierra natal.\n\n'Sí, sí, todo eso está muy bien, pero aun así podrías ser ${PLAYERNAME:un[m]|una[f]} Tuk de algún tipo. ¡Ja! Bromeo, por supuesto. Incluso si no eres ${PLAYERNAME:un[m]|una[f]} Tuk, digo que eres ${PLAYERNAME:primo mío[m]|prima mía[f]}, y sería terriblemente descortés por mi parte no invitarte a visitarnos en la Comarca. Tendrás que seguir el camino hasta Bree, y luego querrás dirigirte hacia el oeste. Una vez que cruces el río Brandivino, ¡estarás en la Comarca! Ah, pero antes querrás pasar por Cavada Grande para hablar con el Alcalde, el viejo Will Pieblanco. ¡Querrá darte una bienvenida adecuada a la Comarca!\n\n'Ah, y si alguno de los Fronteros te da problemas, ¡solo diles que Fridolin te ha invitado a tomar el té!'",
            "'¡Hola, hola! ¿Eres ${PLAYERNAME:un[m]|una[f]} visitante que viene a la Comarca?\n\n'Entonces es mi deber y mi placer darte la bienvenida a nuestro gran país. Soy Will Pieblanco, Alcalde de Cavada Grande y de toda la Comarca. ¿Quién eres y de dónde procedes?'\n\nTe presentas ante el Alcalde Pieblanco, y él hace una reverencia a su vez. Le hablas de tu hogar, diciendo solo que se encuentra más allá de las Montañas Nubladas, y de tu largo viaje a través de incontables tierras que te llevó a la aldea de Musgovilla, en la Ciénaga de los Cisnes. Allí conociste a Fridolin Tuk, dices, y el Alcalde Pieblanco suelta una risita para sí.\n\n'Sería Fridolin, ¿no? Tss. ¡Siempre es un Tuk! Bueno, por mi parte, me alegra que hayas venido a visitarnos. Si tú y los tuyos son de verdad primos lejanos nuestros, ¡entonces digo que eres pariente mío! Eres ${PLAYERNAME:bienvenido[m]|bienvenida[f]} a permanecer en la Comarca todo el tiempo que desees, . Hay muchas villas y pueblos excelentes en la Comarca, así que te sugiero que los visites todos. Después de todo, ¡ya he oído más que suficientes quejas sobre mi supuesto favoritismo!\n\n'No obstante, estoy seguro de que la buena gente de la Comarca agradecería la ayuda de ${PLAYERNAME:un[m]|una[f]}un  de tu... estatura.'",
            "Un Hogar Hobbit Lejos del Hogar",
            "Habla con el Alcalde Will Pieblanco fuera del Agujero del Agujero Municipal, en Cavada Grande",
            "El Alcalde Will Pieblanco puede encontrarse fuera del Agujero del Agujero Municipal en Cavada Grande, en la Comarca.\n\nA pesar de tus protestas, Fridolin Tuk cree que eres ${PLAYERNAME:un primo lejano[m]|una prima lejana[f]} y extraordinariamente ${PLAYERNAME:alto[m]|alta[f]} de los Tuk, y piensa que deberías visitar las tierras de la Comarca. Deberías hablar con el Alcalde de la Comarca, Will Pieblanco.",
        }
    },
    [422] = {
        nameES = "Un Asado Humilde",
        objectivesES = {
            "Culhuc está en Lhan Garan, cerca del horno junto al sendero del paseo ribereño.\n\nPrueba el asado junto a Culhuc en Lhan Garan.",
            "Culhuc está esperando oír tu opinión sobre su plato.\n\nHabla con Culhuc en Lhan Garan.",
            "Un Asado Humilde",
            "'¿Sabroso pero un poco difícil de masticar? Yo también lo pensé. Estoy seguro de que mi próximo intento dará mejores resultados. ¡Me alegra haberte pedido que reunieras tanta carne!'",
            "Prueba el avanc asado",
            "Estaba delicioso pero... algo duro",
            "Habla con Culhuc",
            "'¡Preparé un asado sencillo para ti! Al fin y al cabo, fuiste tú quien consiguió la carne para mí. Me gustaría oír qué te pareció el plato.'",
            "A Culhuc le gustaría que pruebes su plato más reciente.",
        }
    },
    [445] = {
        nameES = "Un Mundo Más Grande",
        objectivesES = {
            "Un Mundo Más Grande",
            "Habla con Eleri sobre la Marca de la Mano Blanca",
            "'Por ahora deberíamos ayudar a la gente de Musgovilla a recuperarse de este ataque. ¿Prestarás tu ayuda? Te has visto envuelto en esto, igual que yo. Si lo que buscas es una vida de aventura, te aseguro que parece que la has encontrado... ¡o que ella te ha encontrado a ti!\n\n'Te has convertido en parte de un mundo más grande, ${PLAYER}, y puede ser distinto del que conocías hasta ahora. Deben afrontarse peligros y oponerse a amenazas, y superarlas, si tienes predisposición a luchar contra ellas. No todos lo tienen... pero juzgo que tú no estarás muy lejos al triunfo y la victoria.'",
            "'¿Qué significado podría tener esta marca? ${PLAYER}, ¿preguntarás a Eleri si ha visto este símbolo antes de hoy?'",
            "'No, no he visto este símbolo antes.'",
            "Meneldir dice que el ataque de los uruk contra Musgovilla es una señal de que no puedes evitar los peligros que se ciernen sobre la Ciénaga de los Cisnes. Te has convertido en parte de un mundo más grande.",
            "Eleri se alza sobre los cadáveres de los uruk saqueadores, pensando en los acontecimientos del ataque.",
            "Habla con Meneldir",
            "'¿La Mano Blanca? No, no he visto este símbolo antes... y eso me inquieta. ¿Qué nuevo peligro podría significar?'",
            "Meneldir luce una expresión preocupada.",
            "'¿Ha visto Eleri este símbolo antes?'",
        }
    },
