    [3375] = {
        nameES = "Carrera de Gallina",
        objectivesES = {
            "Llega a las afueras de Glân Vraig",
            "¡Has sobrevivido!",
            "Sobrevive al viaje hasta Glân Vraig.",
            "Carrera de Gallina",
            "Te han engañado. Parece que esta gallina estaba destinada a ser la cena de las fuerzas de Angmar. Salva tu pellejo y llega a Glân Vraig.",
        }
    },
    [3376] = {
        nameES = "Pollos de vuelta al gallinero",
        objectivesES = {
            "Pollos de vuelta al gallinero",
            "Colocas al pollo en el suelo y este intenta escapar de nuevo, aunque sin éxito",
            "Recupera el primer pollo escapado",
            "Habla con Mushêndu",
            "Un granjero local fuera de Urmâkh ha pedido ayuda para reunir sus pollos escapados.",
            "'Me alegra que hayas podido ayudar a Mushêndu. Me han enviado a traerte de regreso a Urmâkh, hay otros asuntos allí que requieren tu atención.'",
            "Colocas al pollo en el suelo y este asiente ligeramente en señal de agradecimiento. O quizás vio un gusano en la tierra",
            "Colocas al pollo en el suelo y le dices que se mantenga alejado de los chacales. Te parpadea",
            "Recupera los pollos escapados de Mushêndu.",
            "Encuentra al explorador",
            "Habla con Mushêndu fuera del corral de los pollos.",
            "Recupera el tercer pollo escapado",
            "'Hashtal-gûr, ${PLAYERNAME:amigo[m]|amiga[f]}. Me alegra que finalmente hayan enviado a alguien. Estas piernas no son tan ágiles y frescas como antes. Es difícil subir y bajar estas colinas. Mis pollos se han escapado de nuevo. Lo único para lo que parecen tener talento. Debe haber gusanos más jugosos al otro lado de la cerca. Sin embargo, son unos malditos tontos, hay chacales que merodean por estas colinas. Pocas cosas son una comida tan buena para esas bestias como un pollo.\n\n¿Podrías reunirlos antes de que les pueda pasar algo malo?'",
            "Habla con el granjero Mushêndu.",
            "Colocas al pollo en el suelo, seguro dentro del corral de Mushêndu, y le das una charla seria sobre quedarse adentro",
            "Encuentra al explorador.",
            "Habla con el granjero Mushêndu",
            "Recupera el cuarto pollo escapado",
            "Cierras la puerta detrás de ti. Los pollos intercambian una mirada significativa, quizás planeando su próxima escapada",
            "'Gracias. Otros hablan de mejorar Urmâkh, pero tú realmente estás haciendo algo al respecto. Gracias por encontrar todos mis pollos y devolverlos a salvo, es un gran alivio.'",
            "Recupera el segundo pollo escapado",
        }
    },
    [3390] = {
        nameES = "Cortar el bosque",
        objectivesES = {
            "Derrota a los Ucornos en la Arboleda Muerta (${NUMBER}/${TOTAL})",
            "Totâkhri chilla, ¡dejando escapar un agudo grito de batalla!",
            "Quema los extraños retoños (${NUMBER}/${TOTAL})",
            "Encuentra y derrota a Totâkhri, la Raíz Podrida.",
            "'Esta arboleda me llena de desesperación. Anhelo que vuelva a ser exuberante y verde, ojalá vuelva a la salud pronto.'",
            "Totâkhri cae, crujiendo mientras su corteza se parte y se agrieta",
            "Encuentra y derrota a Totâkhri, la Raíz Podrida",
            "Cortar el bosque",
            "La podredumbre de Adagím se está extendiendo. Amenaza con traer la plaga a Kighân. Corta los árboles inquietos y quema la plaga en la Arboleda Muerta.",
            "Derrota a los Ucornos en la afectada Arboleda Muerta y quema sus retoños.",
            "Ucornos derrotados en la Arboleda Muerta (${NUMBER}/${TOTAL})",
            "Retoños extraños quemados (${NUMBER}/${TOTAL})",
        }
    },
    [3419] = {
        nameES = "Civilian Defence",
        objectivesES = {
            "Do not allow any trolls to reach the women and children",
            "Civilian Defence",
            "A troll has reached the women and children!",
            "Defeat the trolls",
            "The enemy is making a final assault on the raised central area of the Glittering Caves. Protect the civilians that are gathered there and defeat all enemies.\n\nMerit Rating\n\nThis quest starts with <rgb=#FFFF00>full</rgb> Merit Rating.\n\n<rgb=#FF0000>Major Point Loss</rgb>\n- Barricade destroyed\n\n<rgb=#FF0000>Moderate Point Loss</rgb>\n- Barricade Guard defeated\n- Orc Defiler heals a Troll\n- Civilian attacked",
            "Protect the civilians at the central camp and defeat the trolls.",
        }
    },
    [3420] = {
        nameES = "Civilian Defence",
        objectivesES = {
            "The enemy is making a final assault on the raised central area of the Glittering Caves. Protect the civilians that are gathered there and defeat all enemies.\n\nMerit Rating\n\nThis quest starts with <rgb=#FFFF00>full</rgb> Merit Rating.\n\n<rgb=#FF0000>Major Point Loss</rgb>\n- Barricade destroyed\n\n<rgb=#FF0000>Moderate Point Loss</rgb>\n- Barricade Guard defeated\n- Orc Defiler heals a Troll\n- Civilian attacked",
            "Civilian Defence",
            "Protect the civilians at the central camp and defeat the trolls.",
            "Defeat the trolls",
        }
    },
    [3439] = {
        nameES = "Poción purificadora",
        objectivesES = {
            "'¡Ah! Justo a tiempo. El último paso del proceso es añadir las hierbas que has recogido para mí. Después solo necesita reposar unos minutos y la poción estará lista.'",
            "Calengil te ha pedido que recojas algunas hierbas para él como parte de una poción que está creando para limpiar una oscura corrupción de las ruinas cerca de Duillond.",
            "Devuelve las hierbas que recogiste a Calengil",
            "'Encontrarás que la hierba crece en las orillas del río bajo Duillond, corriendo de norte a sur.'",
            "'¿Has decidido ayudarme? Excelente. Conozco una poción que debería limpiar la corrupción de las ruinas de Dol Ringwest. Tengo la mayoría de los ingredientes que necesito, pero me falta una hierba: una hierba fragante que crece en las orillas del río, que corre de norte a sur bajo Duillond.\n\nEs sencillo recogerla, y lo haría yo mismo, pero la infusión está en una etapa delicada y debo vigilarla de cerca. ¿Podrías recoger las hierbas que necesito, ${PLAYER}?'",
            "'La poción aún se está preparando, pero pronto necesitaré infusionarla con las hierbas que te pedí.'",
            "Recoge hierbas húmedas y fragantes (${NUMBER}/${TOTAL})",
            "Las hierbas se pueden encontrar a lo largo de la ribera del río debajo de Duillond. \n\nCalengil te ha pedido que recuperes las hierbas que necesita para completar la poción purificadora.",
            "Calengil está en Duillond, al norte de Celondim.\n\nDebes devolver las hierbas que recogiste a Calengil.",
            "Hierbas húmedas y fragantes recogidas (${NUMBER}/${TOTAL})",
            "Poción purificadora",
        }
    },
    [3446] = {
        nameES = "Purificando la madera podrida",
        objectivesES = {
            "'Me entristece que tengamos que atacar el bosque de esta manera, pero es necesario para ralentizar la infección. Has hecho un buen trabajo. Volvamos a Sul Madásh.'",
            "Ucornos eliminados en Hordírid (${NUMBER}/${TOTAL})",
            "Árboles corrompidos purificados (${NUMBER}/${TOTAL})",
            "¡Un Ucorno de aspecto peligroso se ha despertado!",
            "Purifica los árboles corrompidos (${NUMBER}/${TOTAL})",
            "Derrota al Ucorno despiadado de Adagím",
            "Purificando la madera podrida",
            "Tu misión es viajar a Hordírid al noroeste para detener a los peligrosos Ucornos y limpiar los árboles corrompidos en la zona.",
            "Derrota a los Ucornos en Hordírid (${NUMBER}/${TOTAL})",
        }
    },
    [3447] = {
        nameES = "Purificando las ruinas",
        objectivesES = {
            "Regresa a Calengil en Duillond, al este de Dol Ringwest",
            "Dol Ringwest está al oeste de Duillond.\n\nCalengil te pidió que vertieras el brebaje purificador en el suelo, en la base de las dos torres que permanecen en pie en las ruinas de Dol Ringwest.",
            "Usa el brebaje cerca de la primera torre",
            "Encuentra la segunda torre de Dol Ringwest",
            "'El brebaje está listo; solo queda rociarlo sobre el suelo dentro de las ruinas de Dol Ringwest. Fomentará y acelerará el crecimiento de las vides naturales que suelen encontrarse en estos lugares, tanto que para el final de la próxima primavera las ruinas estarán cubiertas por una gran masa de ellas. En poco tiempo, reducirán las ruinas a escombros, devolviéndolas a la naturaleza prístina una vez más.\n\nTe ofrezco el honor de esta tarea, pues ahora veo que no puedo destruir el lugar que tanto amé, incluso en su estado ruinoso. Vierte el brebaje en el suelo bajo las dos torres que permanecen en pie entre las ruinas.\n\nEl tiempo y las fuerzas de la naturaleza harán el resto sin nuestra ayuda.'",
            "Usa el brebaje purificador aquí",
            "Encuentra la primera torre de Dol Ringwest",
            "Usa el brebaje cerca de la segunda torre",
            "Calengil está en Duillond, al este de Dol Ringwest.\n\nDebes regresar con Calengil e informarle que tu tarea en las ruinas de Dol Ringwest está completa.",
            "Purificando las ruinas",
            "'¿Has estado en Dol Ringwest? Está al oeste de aquí.'",
            "Brebaje usado",
            "'Gracias, ${PLAYER}. Me duele saber que nunca más caminaré entre las torres, que recuerdo de mi juventud, pero es mejor esto que dejar la Tierra Media sabiendo que son hogar de criaturas de oscuridad.'",
            "'Dol Ringwest se encuentra al oeste. Lleva el brebaje a las torres.'",
            "Calengil ha preparado su brebaje y te ha ofrecido el honor de limpiar Dol Ringwest. El brebaje, con el tiempo, fomentará el crecimiento de grandes vides que envolverán las ruinas, derribándolas y devolviéndolas a la naturaleza prístina.",
        }
    },
    [3452] = {
        nameES = "Despeja los Caminos",
        objectivesES = {
            "'Todavía hay osos salvajes y feroces que asolan los caminos. Continúa cazando a las bestias y vuelve a mí cuando hayas logrado reducir su número.'",
            "Derrota osos en el Valle de Thráin (${NUMBER}/${TOTAL})",
            "'Gracias por tu ayuda con los osos. Gracias a ti, el camino volverá a ser seguro.'",
            "Osos derrotados en el Valle de Thráin (${NUMBER}/${TOTAL})",
            "Osos feroces se han vuelto numerosos y audaces al norte de Noglond, a lo largo del camino que atraviesa el Valle de Thráin, haciendo que viajar por el valle sea inseguro.",
            "'Hubo un tiempo en que nuestros cazadores mantenían bajo control el número de osos, pero, por desgracia, las bestias se han multiplicado en los últimos años. Es vergonzoso, en verdad, que hayamos permitido que lo salvaje invada nuestros caminos. Mientras los enanos habiten aquí, los senderos deberían ser seguros.\n\n'Si quieres ayudar, patrulla hacia el norte desde Noglond hasta la Hondonada del Cazador y elimina cualquier bestia que encuentres.\n\n'Con tu ayuda, volveremos a hacer seguro el camino.'",
            "Despeja los Caminos",
            "'Los caminos deberían ser seguros, al menos por un tiempo, gracias a ti, ${PLAYER}.'",
            "'Nadie se ha esforzado en mantener los caminos despejados durante mucho tiempo. Bueno, ¡eso va a cambiar!'",
            "La Hondonada del Cazador se encuentra al norte de Noglond.\n\nKetill te ha pedido que caces osos en la Hondonada del Cazador y reduzcas su número.",
            "Ketill está en Noglond, al sur de la Mansión de Thorin.\n\nDebes regresar con Ketill e informarle del resultado de tu patrulla.",
        }
    },
    [3464] = {
        nameES = "Despejando la Ruta del Sur",
        objectivesES = {
            "Ulâmul la Garra derrotado",
            "'Has hecho un gran trabajo, ${PLAYER}, al hacer que estas rutas sean seguras nuevamente al poner fin a los terrores que Ulâmul la Garra y sus compañeros han causado. Regresemos a Iridír.'",
            "Tu misión es investigar la zona donde ha habido muchos informes de bandidos y ponerles fin, así como a su líder, Ulâmul la Garra.",
            "Derrota a Ulâmul la Garra",
            "Despejando la Ruta del Sur",
            "¡Ulâmul la Garra ha llegado!",
            "¡Ulâmul la Garra ha llegado! ¡Derrótalo!",
            "Descubrir emplazamientos del ataque (${NUMBER}/${TOTAL})",
            "Emplazamiento del ataque descubierto",
            "Bandidos derrotados (${NUMBER}/${TOTAL})",
            "Derrota a los bandidos (${NUMBER}/${TOTAL})",
        }
    },
    [3476] = {
        nameES = "Capa del Jinete Negro",
        objectivesES = {
            "Busca señales del \\qJinete Negro\\q",
            "Odovacar Bolger está en su casa, en lo alto de la colina que está en el centro de Bolgovado.\n\nOdovacar Bolger te envió a buscar señales del Jinete Negro, pero todo lo que has encontrado es una capa negra arruinada. Deberías traer la capa negra a Odovacar.",
            "El \\qJinete Negro\\q fue visto en los campos de Cam Barroso, al este de Bolgovado.\n\nOdovacar Bolger te dijo que uno de sus vecinos, Cam Barroso, informó que el Jinete Negro estaba en sus tierras, siendo perseguido por lobos. Odovacar te ha pedido que vayas a buscar al \\qJinete\\q sin caballo.",
            "'¿No pudiste encontrar ninguna señal de ese \\qJinete Negro\\q?'",
            "Capa del Jinete Negro",
            "Odovacar Bolger te ha enviado a perseguir al supuesto Jinete Negro que ha estado rondando sus pocilgas por la noche.",
            "'Quiero que encuentres a ese tipo de la túnica negra y descubras qué está pasando, ${PLAYER}. Lo vieron siendo perseguido por lobos en los campos de Cam Barroso, al este de Bolgovado.'",
            "'¡Ja! Esa es sin duda una capa del tamaño de un hobbit. Debió engancharse mientras huía.\n\n'No te preocupes por perder su rastro. ¡Pronto lo atraparemos!'",
            "Trae la capa negra a Odovacar Bolger",
            "'Cam Barroso acaba de decirme que uno de sus ayudantes vio a ese supuesto Jinete Negro dirigiéndose hacia el este, a pie. Ni rastro de caballo, ni siquiera de un poney.\n\n'Cam dice que lo vieron corriendo por unos campos suyos, perseguido por lobos. Ya es bastante tener que lidiar con molestias como estos \\qJinetes Negros\\q, ¿y ahora también debemos preocuparnos por los lobos?\n\n'Si ese tipo acaba siendo devorado por lobos, nunca sabré qué está pasando aquí, así que será mejor que hagas algo al respecto. Ve a los campos de Cam Barroso, al este de Bolgovado, y busca cualquier señal de ese \\qJinete Negro\\q.'",
        }
    },
    [3479] = {
        nameES = "Cierra sus madrigueras",
        objectivesES = {
            "Hay madrigueras de musarañas al este de Cavada Grande, más allá de los Campos de Cavada.\n\nRuby Piedraprima está molesta por la destrucción de la vegetación causada por las musarañas y quiere que cierres algunas de sus madrigueras.",
            "'¡Gracias por tu ayuda, ${PLAYERNAME:Frontero[m]|Frontera[f]} ! Eso debería disuadir a las musarañas de cavar cerca del pueblo, al menos por un tiempo.'",
            "Ruby Piedraprima está en Cavada Grande, en su casa al sureste de la estatua de Marcho y Blanco en el centro del pueblo.\n\nRuby estará encantada de saber que has cerrado algunas de las madrigueras de musaraña cerca del pueblo.",
            "Cierra las madrigueras de musarañas (${NUMBER}/${TOTAL})",
            "Cierra sus madrigueras",
            "Madrigueras de musarañas cerradas (${NUMBER}/${TOTAL})",
            "'Hay madrigueras de musarañas al este, más allá de los Campos de Cavada. ¡Tienen que cerrarse antes de que las bestias caven más cerca del pueblo!'",
            "'¡Me alegra que ya no tengamos que preocuparnos por esas musarañas excavadoras!'",
            "'¡Gracias por encargarte del problema de las musarañas!'",
            "'¡Eres justo el tipo de persona que esperaba que apareciera: ${PLAYERNAME:un Frontero[m]|una Frontera[f]}!\n\nMi hermano en Tejonera es Frontero, así que normalmente le pediría ayuda con esto, pero Tejonera está muy lejos de aquí y realmente quiero que este problema se resuelva lo antes posible.\n\nHay una terrible plaga de musarañas al este de aquí, más allá de los Campos de Cavada, y están cavando profundamente en la tierra y arruinando la vegetación. Si puedes encontrar algunas de sus madrigueras y cerrarlas, eso debería evitar que esas bestias sucias se acerquen al pueblo. ¡Es tu deber ayudarme con esto, ${PLAYERNAME:Frontero[m]|Frontera[f]}!'",
            "La población de musarañas cerca de Cavada Grande ha aumentado enormemente recientemente, y Ruby Piedraprima quiere que los Fronteros hagan algo al respecto.",
        }
    },
    [3495] = {
        nameES = "Con Collar",
        objectivesES = {
            "Al observar de cerca este tosco collar, puedes ver que no es obra de Elfos ni de enanos.\n\nQuizás Ovorlas pueda obtener alguna información del collar. Debes entregárselo en el campamento élfico en el extremo norte de Nen Hilith.",
            "'Conozco este trabajo. Es obra de trasgos. Debemos informar a los demás en Celondim. ¡Si los trasgos se han vuelto tan agresivos, debemos hacer lo que podamos para expulsarlos de nuestros hogares!'",
            "Lleva el collar de hierro a Ovorlas",
            "Descubriste un tosco collar de hierro en el cuello de un lobo en el valle de Nen Hilith. Es posible que el collar brinde información sobre el problema que ha surgido allí.",
            "Con Collar",
            "Ovorlas está en el campamento élfico en el extremo norte de Nen Hilith.\n\nDebes llevar el collar a Ovorlas y ver si significa algo para él.",
            "'¿Qué necesitas?'",
        }
    },
    [3498] = {
        nameES = "Recolectando Alas de Crébain",
        objectivesES = {
            "Aves molestas se han convertido en una plaga en los campos de Lintrev.",
            "Alas de Crébain recolectadas (${NUMBER}/${TOTAL})",
            "Deberías llevar las alas de Crébain a Adan Rhuvyg.\n\nAdan está en Lintrev.",
            "Recolectando Alas de Crébain",
            "Adan Rhuvyg te ha pedido que recolectes alas de Crébain en los huertos de Lintrev.\n\nLintrev está en el Valle de los Fuertes.",
            "Regresa con Adan",
            "'¡Has regresado! ¡Excelente! Los granjeros estarán contentos de que hayas ayudado en sus campos y ahora los dedos de los pies de todos estarán más seguros.'",
            "'¡Oh, hola! ¡Eres ${PLAYERNAME:nuevo[m]|nueva[f]} aquí, ¿verdad?! Tienes ese aire de ${PLAYERNAME:aventurero[m]|aventurera[f]}, y gente como tú siempre parece estar buscando trabajos para ganar unas monedas extra. ¡Pues tengo tanto monedas como trabajo, si estás dispuesto!\n\n'Los huertos están infestados por aves molestas parecidas a cuervos. Son muy extrañas, se comen todas las semillas y ¡picotean tus dedos si intentas espantarlas! Elimínalas, pero tráeme sus alas. Deseo estudiarlas en detalle.'",
            "Recolecta alas de Crébain (${NUMBER}/${TOTAL})",
        }
    },
    [3514] = {
        nameES = "Recomendaciones",
        objectivesES = {
            "Talk to Orion to continue",
            "'I commend you!'",
            "'Take some Commendations and prepare for war!'",
            "Recomendaciones",
            "Grant Palantir testers Commendations to buy their PvMP rewards.",
            "By completing this quest, you will earn Commendations to be spent on PvMP rewards and advancement.",
        }
    },
