    [4428] = {
        nameES = "Tambores de guerra",
        objectivesES = {
            "Tambores de guerra",
            "Morgul-troll drummers have arrived on the field to inspire their vile allies to attack Minas Tirith with a renewed ferocity. They must be defeated with haste to stem the tide of frenzied Morgul-orcs.\n\nThis quest starts with <rgb=#FFFF00>empty</rgb> Merit Rating.\n\n<rgb=#00FF00>Merit Gain:</rgb>\n* Defeat the Morgul-troll drummers\n* Do not allow more than two waves of frenzied Morgul-orcs to attack the wall",
            "Morgul-troll drummers defeated (${VALUE}/4)",
            "Morgul-troll drummers have arrived on the field. Defeat them quickly to stem the tide of frenzied Morgul-orcs.",
        }
    },
    [4429] = {
        nameES = "Tambores de guerra",
        objectivesES = {
            "Morgul-troll drummers have arrived on the field to inspire their vile allies to attack Minas Tirith with a renewed ferocity. They must be defeated with haste to stem the tide of frenzied Morgul-orcs.\n\nThis quest starts with <rgb=#FFFF00>empty</rgb> Merit Rating.\n\n<rgb=#00FF00>Merit Gain:</rgb>\n* Defeat the Morgul-troll drummers\n* Do not allow more than two waves of frenzied Morgul-orcs to attack the wall",
            "Tambores de guerra",
            "Morgul-troll drummers defeated (${VALUE}/6)",
            "Morgul-troll drummers have arrived on the field. Defeat them quickly to stem the tide of frenzied Morgul-orcs.",
        }
    },
    [4435] = {
        nameES = "Ducks and Drakes",
        objectivesES = {
            "Children can be found by the pond in the Rohan Eastfold Homesteads.\n\nYou should join the children in their 'ducks and drakes' game.",
            "Ducks and Drakes",
            "Skimmed a stone (${NUMBER}/${TOTAL})",
            "'Do you know how to play 'ducks and drakes'? I will teach you! Just pick up a stone, the flat smooth ones are the best, and throw it against the water like this. The one who scores the most bounces wins!'",
            "When neighbours work together, the Rohan Eastfold Homesteads will shine as bright as the beacons.",
            "'Some of the children in the village seem a little bored this afternoon. I think they went to the mountain pond to play 'ducks and drakes'. Are you any good at that game? Well then, you should join them.'",
            "Skim stones on the pond (${NUMBER}/${TOTAL})",
        }
    },
    [4441] = {
        nameES = "Embotando las armas de guerra",
        objectivesES = {
            "Orcos derrotados en Tharháth (${NUMBER}/${TOTAL})",
            "Destruye los estantes de armas de orcos y derrota a los Orcos en Tharháth, cerca del Tramo de Nâmbadir.",
            "Investiga la parte trasera del campamento",
            "Los Orcos han establecido un campamento cerca del Tramo de Nâmbadir. Tu tarea es sabotear sus armas y derrotar a cualquiera que se interponga en tu camino.",
            "Algo grande ruge de ira al ser perturbado",
            "Derrota al Devastador Utûgi",
            "'Deberíamos llevarte de regreso a Urmâkh. Ven, debemos difundir la buena noticia de tu victoria aquí.'",
            "Derrota a los Orcos en Tharháth (${NUMBER}/${TOTAL})",
            "Estantes de armas de orcos destruidos (${NUMBER}/${TOTAL})",
            "Derrota al Devastador Utûgi.",
            "Embotando las armas de guerra",
            "Investiga el ruido que proviene de la parte trasera del campamento.",
            "Destruye los estantes de armas de orcos (${NUMBER}/${TOTAL})",
        }
    },
    [4449] = {
        nameES = "Tierras Brunas - Algraig I",
        objectivesES = {
            "Talk to Ransroth to continue",
            "'Alright, soon the Algraig will consider you an Acquaintance. Ready?'",
            "'Greetings traveller, I can make you an \\qAcquaintance\\q of the Algraig, if you wish.\n\n'Sound good?'",
            "By completing this quest, you will be considered an Acquaintance of the Algraig.",
            "Tierras Brunas - Algraig I",
        }
    },
    [4450] = {
        nameES = "Tierras Brunas - Algraig II",
        objectivesES = {
            "'Interested in more Algraig reputation? Speak to me again when you are ready and I shall help you with this.'",
            "'Alright, soon you will be a Friend of the Algraig. Ready?'",
            "By completing this quest, you will be considered a Friend of the Algraig.",
            "Talk to Ransroth to continue",
            "Tierras Brunas - Algraig II",
        }
    },
    [4451] = {
        nameES = "Tierras Brunas - Algraig III",
        objectivesES = {
            "Talk to Ransroth to continue",
            "Tierras Brunas - Algraig III",
            "'Alright, soon you will be an Ally of the Algraig. Ready?'",
            "'I didn't even get to be one of the popular bestowers, like one of the level up quest bestowers. Oh, and did you notice who the level 50 level up quest bestower is? Yep, Maid of Lions. There's hubris for you!\n\n'There I go again, you probably don't care about the problems of a little-old reputation bestower, do you? Let me get to the matter at hand.\n\n'If you want to be an \\qAlly\\q of the Algraig, speak to me again.'",
            "By completing this quest, you will be considered an Ally of the Algraig.",
        }
    },
    [4452] = {
        nameES = "Tierras Brunas - Algraig IV",
        objectivesES = {
            "By completing this quest, you will be considered Kindred of the Algraig.",
            "Talk to Ransroth to continue",
            "'Alright, soon you will be Kindred of the Algraig. Ready?'",
            "Tierras Brunas - Algraig IV",
            "'Shall we make you a Kindred of the Algraig?'",
        }
    },
    [4453] = {
        nameES = "Dunland - Dunlendings I",
        objectivesES = {
            "Dunland - Dunlendings I",
            "Talk to Ransroth to continue",
