    [8010] = {
        nameES = "Level Up: Volume II: Book I (Warden)",
        objectivesES = {
            "'Meow! Hello, I'm Elevensies! Although I type slowly, due to my furry paws, I can help you complete the Epic quest series. If you complete this quest, you'll be flagged as having completed Book I of the Epic series.",
            "'Alright, when you complete this quest you'll be flagged as having completed Book I of the Epic. Have fun!'",
            "Completion of this quest will flag your character has having completed all the quests in Book I of the Epic quest series for Volume II.",
            "Level Up: Volume II: Book I (Warden)",
        }
    },
    [8011] = {
        nameES = "Level Up: Volume II: Book II",
        objectivesES = {
            "'Alright, when you complete this quest you'll be flagged as having completed Book II of the Epic. Have fun!'",
            "'Meow! Back so soon? Well I can complete Book II of the Epic quest series now for you, if you'd like. Just speak to me again.",
            "Level Up: Volume II: Book II",
            "Completion of this quest will flag your character has having completed all the quests in Book II of the Epic quest series for Volume II.",
        }
    },
    [8012] = {
        nameES = "Level Up: Volume II: Book III",
        objectivesES = {
            "Level Up: Volume II: Book III",
            "'Meow! Back so soon? Well now you are up to Book III of the Epic quest series. Want me to complete that now for you? Just speak to me again and I'll flag you appropriately.",
            "Completion of this quest will flag your character has having completed all the quests in Book III of the Epic quest series of Volume II.",
            "'Since you asked so nicely, when you complete this quest you'll be flagged as having completed Book III of the Epic. Have fun and be careful out there!'",
        }
    },
    [8013] = {
        nameES = "Level Up: Volume II: Book IV",
        objectivesES = {
            "Completion of this quest will flag your character has having completed all the quests in Book IV of the Epic quest series of Volume II.",
            "'When this quest is completed, you'll be flagged as having completed Book IV of the Epic. Enjoy!'",
            "'Meow! Are you already up to Book IV of the Epic quest series? Goodness, so many good quests and adventures. I wish my furry paws let me make content as exciting as that, but I'm just a humble, slow typing cat.\n\nOh well, at least I can help you! Just speak to me again.",
            "Level Up: Volume II: Book IV",
        }
    },
    [8014] = {
        nameES = "Level Up: Volume II: Book V",
        objectivesES = {
            "'Meow! Goodness, you are up to Book V of the Epic quest series. That is a very good series of quests, if you ask me. All those bits with Skorgrím and the Dourhands, and then you end with a Dragon. Terribly exciting!\n\nOh well, you'll be able to skip all that once you complete this quest.",
            "Completion of this quest will flag your character has having completed all the quests in Book V of the Epic quest series of volume II.",
            "Level Up: Volume II: Book V",
            "'Here we go! When you complete this quest you'll be flagged as having completed Book V of the Epic.'",
        }
    },
    [8015] = {
        nameES = "Level Up: Volume II: Book VI",
        objectivesES = {
            "'Meow! Well, well, you are up to Book 6 of the Epic quest series. I wonder, are you getting tired of speaking to me yet? No? Well good! Because there so much left to the Epic quest after this book.\n\nBut that's for later. For now, if you want to complete Book 6 of the Epic quest, you'll be all set once you complete this quest.",
            "'Well, you know how this works by now. Complete this quest and you'll have Book VI of the Epic quest completed.'",
            "Completion of this quest will flag your character has having completed all the quests in Book VI of the Epic quest series of Volume II.",
            "Level Up: Volume II: Book VI",
        }
    },
    [8016] = {
        nameES = "Level Up: Volume II: Book VII",
        objectivesES = {
            "'Meow! I just realized, you are talking to me. I'm a cat! How is that possible? That's just strange... Oh well, would you like to be flagged as having completed Book VII of the Epic quest series? If so, speak to me again!",
            "'Do I even need to tell you how this works? Oh well, just in case you weren't paying attention. Completion of this quest will flag you has having completed Book VII of the Epic quest.'",
            "Completion of this quest will flag your character has having completed all the quests in Book VII of the Epic quest series of Volume II.",
            "Level Up: Volume II: Book VII",
        }
    },
