    [8901] = {
        nameES = "Miniaventura: La última batalla de Svalfang",
        objectivesES = {
            "Se te ha encomendado derrotar al gigante de las colinas Svalfang en el Bosque Salvaje.",
            "Deberías encontrar a Svalfang.\n\n<rgb=#FF0000>Si Radhril no está y la habilidad Llamar a Radhril no está disponible, intenta usar el comando /pet release.</rgb>",
