    [8978] = {
        nameES = "Miniaventura: Las últimas brasas de Nûrz Ghâshu",
        objectivesES = {
            "Tras escapar de la grieta de Nûrz Ghâshu, algunos de los Ghâshfra supervivientes se refugiaron en el monte Gundabad, donde su maestría con el fuego les ha convertido en poderosos aliados de Gorgar el Despiadado.",
