    [9083] = {
        nameES = "Miniaventura: Alas sobre Grálinvarth",
        objectivesES = {
            "¿Completado?",
            "Enanos heridos auxiliados en Grálinvarth (${CURRENT}/${MAX})",
            "Un ataque reciente de la Horda de Escarcha ha amenazado con desbordar a los enanos que montan guardia en Grálinvarth.",
