    [9403] = {
        nameES = "Oh, ratas",
        objectivesES = {
            "Destruye nidos de ratas (${NUMBER}/${TOTAL})",
            "Derrota a los ratas en Sul Madásh (${NUMBER}/${TOTAL})",
            "Oh, ratas",
            "'¡Qué alivio librarnos de esa plaga de ratas que asola nuestro hogar! Aunque... estoy seguro de que volverán con el tiempo. Regresa a Sul Madásh.'",
            "¡Un ratón monstruoso aparece para defender los nidos!",
            "Tu misión es librar a Sul Madásh de su problema de ratas. Están creciendo en número y se están convirtiendo en un problema para el asentamiento. Las ratas deben ser detenidas y sus nidos destruidos.",
            "Ratas eliminadas en Sul Madásh (${NUMBER}/${TOTAL})",
            "Nidos de ratas destruidos (${NUMBER}/${TOTAL})",
            "Derrota al ratón monstruoso",
        }
    },
    [9409] = {
        nameES = "Okurayo the Minstrel",
        objectivesES = {
            "Okurayo the Minstrel",
            "<rgb=#FF0000>Defeat Okurayo before he slips away</rgb>",
            "<rgb=#FF0000>You have left Okurayo unchallenged for too long.</rgb>",
            "A Minstrel has climbed up to your vantage point, shouting insults and egging on our foes. Dispatch him before he whips your enemies into a frenzy.\n\nThis quest starts with <rgb=#FFFF00>empty</rgb> Merit Rating.\n\n<rgb=#00FF00>Merit Gain:</rgb>\n* Defeat Okurayo \n* Defeat Okurayo quickly",
            "Defeat Okurayo the Minstrel quickly",
            "Defeat Okurayo the Minstrel quickly, before he heartens our foes and dispirits our men.",
        }
    },
    [9410] = {
        nameES = "Okurayo the Minstrel",
        objectivesES = {
            "Okurayo the Minstrel",
            "<rgb=#FF0000>Defeat Okurayo before he slips away</rgb>",
            "<rgb=#FF0000>You have left Okurayo unchallenged for too long.</rgb>",
            "A Minstrel has climbed up to your vantage point, shouting insults and egging on our foes. Dispatch him before he whips your enemies into a frenzy.\n\nThis quest starts with <rgb=#FFFF00>empty</rgb> Merit Rating.\n\n<rgb=#00FF00>Merit Gain:</rgb>\n* Defeat Okurayo \n* Defeat Okurayo quickly",
            "Defeat Okurayo the Minstrel quickly",
