    [9992] = {
        nameES = "Racial Traits: High Elves",
        objectivesES = {
            "Racial Traits: High Elves",
            "'Hoom, hum. What are you, little one? Do not tell me, hasty creature. I will find out.\n\n   Eldest of all, the elf-children...\n\n'Hm, yes, that is you. Will you accept the gift of your peoples?'\n\n<rgb=#FF0000>By completing this quest, you will receive racial traits for a high level character.</rgb>",
            "'Room tum, room tum, roomty toom tum.'",
            "Talk to Snowlight to receive your Racial Traits",
            "By completing this quest, you will receive racial traits for a high level character.",
        }
    },
    [9993] = {
        nameES = "Racial Traits: Hobbits",
        objectivesES = {
            "Talk to Snowlight to receive your Racial Traits",
            "'Hoom, hum. What are you, little one? Do not tell me, hasty creature. I will find out.\n\n   Eldest of all, the elf-children;\n   Dwarf the delver, dark are his houses;\n   Ent the earthborn, old as mountains;\n   Man the mortal, master of horses....\n\n'Hm, hm, hm.\n\n   Beaver the builder, buck the leaper,\n   Bear the bee-hunter, boar the fighter;\n   Hound is hungry, hare is fearful...\n\n'Hm, hm.\n\n   Eagle in eyrie, ox in pasture,\n   Hart-horn-crowned; hawk is swiftest,\n   Swan the whitest, serpent coldest...\n\n'A long list, but you do not seem to fit in anywhere!'\n\n<rgb=#FF0000>By completing this quest, you will receive racial traits for a high level character.</rgb>",
            "Racial Traits: Hobbits",
            "By completing this quest, you will receive racial traits for a high level character.",
            "'We shall have to make a new line for you.\n\n   Half-grown hobbits, the hole-dwellers.\n\n'There now, hm, that seems to fit. Will you accept the gift of your peoples?'",
        }
    },
