    [9999] = {
        nameES = "Raid Gear: Burglar",
        objectivesES = {
            "Talk to Avon to continue",
            "'Buckle up buttercup, here comes the gear!'",
            "Raid Gear: Burglar",
            "By completing this quest, you will receive a set of Raid Gear.",
            "'Looking for some sweet raid gear are you? Well, I am the man, er dwarf to help you! I've made just about all this stuff, and while it has crushed my soul, the black lump that is my heart is warmed to see you enjoy these items.\n\n'So, if you'd like a set raid gear, speak to me again.'",
        }
    },
