    [10061] = {
        nameES = "Rain of Death",
        objectivesES = {
            "Shroud the heads of the fallen before hope is lost",
            "Rain of Death",
            "The severed heads of numerous slain Gondorians have been hurled over the walls of Minas Tirith. The warriors and inhabitants of Gondor alike shall soon fall to despair unless the Enemy's vile design is undone.\n\nThis quest starts with <rgb=#FFFF00>empty</rgb> Merit Rating.\n\n<rgb=#00FF00>Merit Gain:</rgb>\n* Shroud the heads of the fallen on the streets of Minas Tirith\n* Shroud the heads of the fallen on the walls of Minas Tirith\n* Rally the people who saw the heads fall upon the city",
            "The severed heads of numerous slain Gondorians have been hurled over the walls of Minas Tirith. The warriors and inhabitants of Gondor alike shall soon fall to despair unless the Enemy's vile design is undone.",
        }
    },
    [10062] = {
        nameES = "Rain of Death",
        objectivesES = {
            "Shroud the heads of the fallen before hope is lost",
            "Rain of Death",
            "The severed heads of numerous slain Gondorians have been hurled over the walls of Minas Tirith. The warriors and inhabitants of Gondor alike shall soon fall to despair unless the Enemy's vile design is undone.\n\nThis quest starts with <rgb=#FFFF00>empty</rgb> Merit Rating.\n\n<rgb=#00FF00>Merit Gain:</rgb>\n* Shroud the heads of the fallen on the streets of Minas Tirith\n* Shroud the heads of the fallen on the walls of Minas Tirith\n* Rally the people who saw the heads fall upon the city",
