    [10439] = {
        nameES = "Rivendell IV",
        objectivesES = {
            "'Alright, soon you will be Kindred of the Elves of Rivendell. Ready?'",
            "Talk to Ransroth to continue",
            "'Are you looking to be welcomed into the inner circle of the Elves of Rivendell? I can help you with that and make you a \\qKindred\\q of the Elves of Rivendell.\n\n'If this sounds good to you, speak to me again!'",
